
from flask import Flask, render_template, jsonify
from pathlib import Path
import csv

app = Flask(__name__)

BASE_DIR = Path(__file__).resolve().parent
PROCESSED_DIR = BASE_DIR / "dataset" / "processed"


def read_spark_csv(folder_name):
    """Read CSV files generated by Apache Spark."""
    folder = PROCESSED_DIR / folder_name

    if not folder.exists():
        print(f"Warning: Folder not found: {folder}")
        return []

    records = []

    for file_path in folder.glob("part-*.csv"):
        try:
            with open(file_path, "r", encoding="utf-8-sig", newline="") as file:
                reader = csv.DictReader(file)
                records.extend(reader)
        except Exception as error:
            print(f"Could not read {file_path}: {error}")

    return records


def to_number(value, default=0):
    try:
        return float(value)
    except (ValueError, TypeError):
        return default


def get_dashboard_data():
    # Read Spark-generated CSV analytics
    popular_pages = read_spark_csv("popular_pages")
    status_summary = read_spark_csv("status_summary")
    daily_traffic = read_spark_csv("daily_traffic")
    cluster_summary = read_spark_csv("cluster_summary")

    # Total requests = sum of all HTTP status counts
    total_requests = sum(
        int(to_number(row.get("total")))
        for row in status_summary
    )

    # Unique visitors = sum of visitors in all K-Means clusters
    unique_visitors = sum(
        int(to_number(row.get("visitor_count")))
        for row in cluster_summary
    )

    # Total bytes = weighted sum of average bytes per visitor
    total_bytes = round(sum(
        to_number(row.get("avg_bytes")) *
        to_number(row.get("visitor_count"))
        for row in cluster_summary
    ))

    # Sort popular pages by number of visits
    popular_pages.sort(
        key=lambda row: to_number(row.get("visits")),
        reverse=True
    )

    # Sort daily traffic by date
    daily_traffic.sort(
        key=lambda row: row.get("request_date", "")
    )

    # Sort clusters by cluster number
    cluster_summary.sort(
        key=lambda row: to_number(row.get("cluster"))
    )

    return {
        "total_requests": total_requests,
        "unique_visitors": unique_visitors,
        "total_bytes": total_bytes,
        "popular_pages": popular_pages[:10],
        "status_summary": status_summary,
        "daily_traffic": daily_traffic,
        "cluster_summary": cluster_summary
    }


@app.route("/")
def home():
    return render_template("index.html")


@app.route("/api/dashboard")
def dashboard_api():
    try:
        return jsonify(get_dashboard_data())
    except Exception as error:
        app.logger.exception("Dashboard data loading failed")
        return jsonify({"error": str(error)}), 500


@app.route("/health")
def health():
    return jsonify({"status": "running"})


if __name__ == "__main__":
    print("\n==========================================")
    print("       WEB USAGE MINING DASHBOARD")
    print("==========================================")
    print("Dashboard: http://127.0.0.1:5000/")
    print("API:       http://127.0.0.1:5000/api/dashboard")
    print("==========================================\n")

    app.run(
        host="127.0.0.1",
        port=5000,
        debug=True,
        use_reloader=False
    )
